import sys

def solve():
    lines = sys.stdin.read().strip().split('\n')
    nums = [int(x.strip()) for x in lines[0].split(',')]
    target = int(lines[1].strip())
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] + nums[j] == target:
                print(f"{i} {j}")
                return

if __name__ == '__main__':
    solve()

